{
  "contract": "ReservaX",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": ["withdraw", "_beforeTokenTransfer"],
    "justification": "These functions interact with the exposed storage variables _status, withdrawNine, and withdrawTen, which are relevant to the target property."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": ["withdraw", "_beforeTokenTransfer"],
    "nesting_bound": {
      "withdraw": 1,
      "_beforeTokenTransfer": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_external_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_external_call",
      "to_marker": "after_external_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_external_call",
      "to_marker": "end"
    },
    "linearization_point": "after_external_call"
  },
  "ghost_state": [
    {
      "name": "inFlightNine",
      "sol_type": "uint256",
      "meaning": "Amount in-flight for token 9 during the callback window",
      "backed_by_storage": false
    },
    {
      "name": "inFlightTen",
      "sol_type": "uint256",
      "meaning": "Amount in-flight for token 10 during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "withdrawNine + inFlightNine <= _totalSupply[9] && withdrawTen + inFlightTen <= _totalSupply[10]",
    "stable_formula": "withdrawNine <= _totalSupply[9] && withdrawTen <= _totalSupply[10]",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "withdrawNine <= _totalSupply[9] && withdrawTen <= _totalSupply[10]",
    "rule": "The exposure invariant ensures that the withdraw amounts do not exceed the total supply during reentrancy."
  }
}
